package com.phoenix.business.web;import com.phoenix.business.domain.AuditLog;import com.phoenix.business.repository.AuditLogRepository;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/audit-logs") @RequiredArgsConstructor @PreAuthorize("hasAnyRole('OWNER','ADMIN')") public class AuditController {private final AuditLogRepository repo;@GetMapping public Page<AuditLog> list(@RequestParam(required=false)String q,@PageableDefault(size=30)Pageable p){return repo.search(q==null||q.isBlank()?null:q,p);}}
